const http = require('http');
const https = require('https');
const { URL } = require('url');
const dns = require('dns');
const crypto = require('crypto');
const net = require('net');

const INTERNAL_RANGES_V4 = [
  { start: 0x00000000, end: 0x00FFFFFF }, // 0.0.0.0/8
  { start: 0x0A000000, end: 0x0AFFFFFF }, // 10.0.0.0/8
  { start: 0x7F000000, end: 0x7FFFFFFF }, // 127.0.0.0/8
  { start: 0xA9FE0000, end: 0xA9FEFFFF }, // 169.254.0.0/16
  { start: 0xAC100000, end: 0xAC1FFFFF }, // 172.16.0.0/12
  { start: 0xC0A80000, end: 0xC0A8FFFF }, // 192.168.0.0/16
];

function ipv4ToInt(ip) {
  const parts = ip.split('.');
  if (parts.length !== 4) return null;
  let result = 0;
  for (let i = 0; i < 4; i++) {
    const octet = parseInt(parts[i], 10);
    if (isNaN(octet) || octet < 0 || octet > 255) return null;
    result = (result * 256) + octet;
  }
  return result >>> 0; // ensure unsigned 32-bit
}

function isInternalIPv4(ip) {
  const num = ipv4ToInt(ip);
  if (num === null) return true; // fail closed
  return INTERNAL_RANGES_V4.some(r => num >= r.start && num <= r.end);
}

function isInternalIPv6(ip) {
  // Block all IPv6 loopback, unspecified, and private ranges
  const normalized = ip.toLowerCase();
  if (normalized === '::1' || normalized === '::' ||
      normalized.startsWith('fc') ||
      normalized.startsWith('fd') || normalized.startsWith('fe80')) {
    return true;
  }
  // Check for IPv4-mapped IPv6
  if (normalized.startsWith('::ffff:')) {
    const v4part = normalized.slice(7);
    if (net.isIPv4(v4part)) return isInternalIPv4(v4part);
  }
  return false;
}

function isInternalIP(ip) {
  if (net.isIPv4(ip)) return isInternalIPv4(ip);
  if (net.isIPv6(ip)) return isInternalIPv6(ip);
  return true; // fail closed on unknown format
}

function validateUrl(urlStr) {
  try {
    const parsed = new URL(urlStr);
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      return { valid: false, reason: 'Invalid protocol' };
    }
    if (parsed.username || parsed.password) {
      return { valid: false, reason: 'Credentials not allowed' };
    }
    if (!parsed.hostname || parsed.hostname.length > 253) {
      return { valid: false, reason: 'Invalid hostname' };
    }
    if (['localhost', '0.0.0.0', '[::]', '[::1]'].includes(parsed.hostname.toLowerCase())) {
      return { valid: false, reason: 'Internal host blocked' };
    }
    // Block numeric IPs directly
    if (net.isIP(parsed.hostname)) {
      if (isInternalIP(parsed.hostname)) {
        return { valid: false, reason: 'Internal IP blocked' };
      }
    }
    return { valid: true, parsed };
  } catch (e) {
    return { valid: false, reason: 'Malformed URL' };
  }
}

const API_KEY = process.env.API_KEY || crypto.randomBytes(32).toString('hex');

function authenticateRequest(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return false;
  const token = authHeader.slice(7);
  if (typeof token !== 'string' || token.length !== API_KEY.length) return false;
  return crypto.timingSafeEqual(Buffer.from(token, 'utf8'), Buffer.from(API_KEY, 'utf8'));
}

async function fetchUrlSafe(urlStr, redirectCount = 0) {
  if (redirectCount > 3) throw new Error('Too many redirects');

  const validation = validateUrl(urlStr);
  if (!validation.valid) {
    throw new Error(`URL validation failed: ${validation.reason}`);
  }

  const { parsed } = validation;

  // Resolve DNS and validate IP at fetch time (no TOCTOU gap)
  const resolvedIP = await new Promise((resolve, reject) => {
    const resolver = new dns.Resolver();
    resolver.setServers(['8.8.8.8', '8.8.4.4']);
    resolver.resolve4(parsed.hostname, (err, addresses) => {
      if (err) {
        resolver.resolve6(parsed.hostname, (err6, addr6) => {
          if (err6) return reject(new Error('DNS resolution failed'));
          return resolve(addr6[0]);
        });
        return;
      }
      resolve(addresses[0]);
    });
  });

  // Validate resolved IP
  if (isInternalIP(resolvedIP)) {
    throw new Error(`Blocked: resolved to internal IP`);
  }

  // Connect directly to the resolved IP to prevent DNS rebinding
  return new Promise((resolve, reject) => {
    const client = parsed.protocol === 'https:' ? https : http;
    const options = {
      hostname: resolvedIP,
      port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80),
      path: parsed.pathname + parsed.search,
      method: 'GET',
      timeout: 5000,
      headers: {
        'Host': parsed.hostname,
        'User-Agent': 'SafeFetcher/1.0'
      },
      // For HTTPS, set servername for SNI
      ...(parsed.protocol === 'https:' ? { servername: parsed.hostname } : {})
    };

    const request = client.request(options, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        fetchUrlSafe(res.headers.location, redirectCount + 1).then(resolve).catch(reject);
        return;
      }
      const chunks = [];
      let totalSize = 0;
      res.on('data', chunk => {
        totalSize += chunk.length;
        if (totalSize > 10240) { request.destroy(); reject(new Error('Response too large')); return; }
        chunks.push(chunk);
      });
      res.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    });
    request.on('error', reject);
    request.on('timeout', () => { request.destroy(); reject(new Error('Timeout')); });
    request.end();
  });
}

const server = http.createServer(async (req, res) => {
  if (req.method !== 'POST' || req.url !== '/fetch') {
    res.writeHead(404);
    res.end('Not found');
    return;
  }

  if (!authenticateRequest(req)) {
    res.writeHead(401);
    res.end('Unauthorized');
    return;
  }

  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 2048) {
      res.writeHead(413);
      res.end('Too large');
      return;
    }
  }

  try {
    const { url } = JSON.parse(body);
    if (typeof url !== 'string') throw new Error('url must be a string');
    const content = await fetchUrlSafe(url);
    res.writeHead(200, { 'Content-Type': 'text/plain' });
    res.end(content);
  } catch (e) {
    res.writeHead(400);
    res.end(e.message);
  }
});

server.listen(3000);
